class MaxStack {
    list<int> values;
    map<int, vector<list<int>::iterator>> positions;

public:
    MaxStack() {}

    void push(int x) {
        values.push_back(x);
        auto it = values.end();
        --it;
        positions[x].push_back(it);
    }

    int pop() {
        int x = values.back();
        values.pop_back();
        positions[x].pop_back();
        if (positions[x].empty()) {
            positions.erase(x);
        }
        return x;
    }

    int top() {
        return values.back();
    }

    int peekMax() {
        return positions.rbegin()->first;
    }

    int popMax() {
        int x = peekMax();
        auto& nodes = positions[x];
        values.erase(nodes.back());
        nodes.pop_back();
        if (nodes.empty()) {
            positions.erase(x);
        }
        return x;
    }
};
